public static MZNAGStudent find(MZNAGStudentId _studentId, boolean _forUpdate = false)
{
    MZNAGStudent student;
    if(_studentId)
    {
        if(_forUpdate)
        {
            student.selectForUpdate(_forUpdate);
        }
        select firstonly student
            where student.MZNAGStudentId == _studentId;
    }
    return student;
}

public static boolean exists(MZNAGStudentId _studentId)
{
    return ( select firstonly RecId from MZNAGStudent
        where MZNAGStudent.MZNAGStudentId == _studentId).RecId != 0;
}

/// <summary>
///
/// </summary>
[SysClientCacheDataMethodAttribute(true)]
public display str courseList()
{
    MZNAGEnrollment enrollment;
    MZNAGCourseTable courseTable;
    str enrolledCourses = "";

    // Loop through all enrolled courses for this specific student
    while select CourseName from courseTable
    exists join enrollment
    where enrollment.CourseId == courseTable.CourseId
       && enrollment.MZNAGStudentId == this.MZNAGStudentId
    {
        // Add a comma separator if there are multiple courses
        if (enrolledCourses)
        {
            enrolledCourses += ", ";
        }
        enrolledCourses += courseTable.CourseName;
    }

    return enrolledCourses;
}
